   820      int bits = GETSOCK_READSOCK(0);
   821      bool any = FALSE;
   822
   823      /* if stopped and still in this state, then we're also waiting for a
   824         connect on the secondary connection */
   825      socks[0] = conn->sock[FIRSTSOCKET];
   826
   827      if(!conn->data->set.ftp_use_port) {
   828        int s;
   829        int i;
   830        /* PORT is used to tell the server to connect to us, and during that we
   831           don't do happy eyeballs, but we do if we connect to the server */
   832        for(s = 1, i = 0; i<2; i++) {
   833          if(conn->tempsock[i] != CURL_SOCKET_BAD) {
   834            socks[s] = conn->tempsock[i];
   835            bits |= GETSOCK_WRITESOCK(s++);
